M = "micro-virol-6"
SUB = "Virology"
T = {
"picorna-struct": [
 ("Naked picornavirus RNA injected into a cell is infectious on its own because the genome:",["Is plus-sense and acts directly as messenger RNA","Carries its own RNA polymerase in the virion","Is double-stranded and so needs no copying","Integrates into the host chromosome first"],0,"VPg and the 3' polyA tail raise its infectivity, but what makes it sufficient is that ribosomes can translate it immediately."),
 ("Pleconaril blocks picornavirus uncoating by binding:",["The canyon floor in VP1 where the receptor docks","Neuraminidase on the virion surface","The internal ribosome entry site of the genome","The 2A protease of the polyprotein"],0,"Its 3-methylisoxazole group distorts the canyon so the capsid cannot be destabilised.",2),
 ("Which capsid polypeptide is cleaved from VP0 only after the genome has been packaged, and is released when the virus binds its receptor?",["VP4","VP1","VP2 only","VP3"],0,"VP0 is cleaved into VP2 and VP4; VP4 stabilises the mature virion and leaves on receptor binding.",3),
 ("A picornavirus messenger RNA has no 5' cap. Ribosomes still load onto it by recognising:",["An internal ribosome entry site","The VPg protein","The polyA tail","A cellular cap donated by the host"],0,"The same loop structure is found in a few cellular messenger RNAs."),
 ("The receptor for poliovirus is:",["PVR, also called CD155","Intercellular adhesion molecule-1","Decay accelerating factor","The coxsackie adenovirus receptor"],0,"Receptor specificity, not the genome, is the main determinant of which tissue each picornavirus damages.")],
"entero": [
 ("A child develops acute flaccid paralysis of one leg after a febrile illness. The virus has destroyed:",["Motor neurons of the anterior horn","Peripheral sensory nerve endings","The neuromuscular junction of the limb","Dorsal root ganglia of the spinal cord"],0,"Poliovirus infection of anterior horn and brainstem motor neurons is cytolytic, hence flaccid rather than spastic weakness.",3),
 ("Herpangina and hand-foot-and-mouth disease are caused by:",["Coxsackievirus A","Coxsackievirus B","Poliovirus","Hepatitis A virus"],0,"Group B is remembered for body disease — pleurodynia, myocarditis — while group A gives the vesicular lesions.",2),
 ("Enteroviruses survive passage through the stomach and mild sewage treatment because the capsid:",["Is stable from pH 3 to 9 and resists detergent","Is enveloped and resists bile salts","Is coated in host glycoprotein","Carries a protective polysaccharide coat"],0,"Rhinovirus is the exception within the family: it is acid-labile."),
 ("Despite the family name, enteroviruses:",["Replicate in the gut but do not cause enteric disease","Cause watery diarrhoea as their main illness","Cannot be recovered from stool","Only infect the respiratory tract"],0,"First-round replication may be in oropharynx, respiratory tract or gastrointestinal tract, but disease comes from the lytic infection of a target tissue elsewhere."),
 ("The name echovirus records that:",["The virus was found before any disease was attributed to it","It echoes the clinical picture of poliovirus disease","It was first isolated from the middle ear","It causes a characteristically biphasic illness"],0,"Enteric cytopathic human orphan — an orphan virus is one without a known disease.")],
"rhino": [
 ("Rhinovirus infection stays in the upper respiratory tract because the virus:",["Is acid-labile and replicates poorly above 33 °C","Binds only to mucin in the nasal cavity","Cannot cross the epithelial basement membrane","Is cleared rapidly by alveolar macrophages"],0,"Both properties together confine it; the nose is cooler than the core.",2),
 ("At least 80% of rhinovirus serotypes attach to:",["Intercellular adhesion molecule-1","CD55, decay accelerating factor","CD155, the poliovirus receptor","Sialic acid on cell glycoproteins"],0,"That receptor is present on epithelial cells, fibroblasts and endothelial cells."),
 ("Why do enteroviruses spread by the faecal-oral route while rhinoviruses do not?",["Rhinovirus is inactivated by gastric acid","Rhinovirus carries a lipid envelope","Enteroviruses are considerably larger","Rhinovirus needs an arthropod vector"],0,"Acid stability is the single difference that sends the two groups to different body sites.",2)],
"corona": [
 ("Coronaviruses resist detergent despite having an envelope because:",["A dense glycoprotein corona covers the envelope","The envelope is cross-linked by matrix protein","The genome is protected by VPg","They replicate inside vesicles"],0,"This is the standing exception to the rule that enveloped viruses are detergent-sensitive.",2),
 ("SARS-CoV and MERS-CoV cause systemic disease and severe pneumonia, unlike other human coronaviruses, because they:",["Replicate well at 37 °C","Lack a spike protein","Use a nuclear replication step","Are transmitted only by aerosol"],0,"Most human coronaviruses have an optimum of 33 to 35 °C and so stay in the upper airway.",3),
 ("The coronavirus protein that mediates both attachment and membrane fusion, and is the target of neutralising antibody, is:",["E2, the spike glycoprotein","E1, the matrix glycoprotein","N, the nucleoprotein","The RNA polymerase"],0,"E1 is the transmembrane matrix protein; E3 hemagglutinin neuraminidase is present only in some strains."),
 ("Coronaviruses account for roughly what share of all upper respiratory tract infections?",["10% to 15%","Under 1%","30% to 40%","More than half"],0,"Their cold is like a rhinovirus cold but with a longer incubation period, averaging 3 days.")],
"noro": [
 ("Norovirus outbreaks are hard to contain on cruise ships mainly because the virus:",["Is highly resistant to the environment and to disinfectants","Is spread by a mosquito vector on board","Has an animal reservoir on the ship","Causes a prolonged viraemia with no symptoms at all"],0,"It is a small capsid virus with a plus-sense RNA genome, resistant even to detergent.",2),
 ("Norovirus produces watery diarrhoea with nausea and vomiting by:",["Damaging the intestinal brush border","Secreting a heat-labile enterotoxin","Invading the intestinal submucosa","Killing the enteric nerve plexus"],0,"Treatment is supportive; diagnosis rests on symptoms plus RT-PCR of the genome.")],
"paramyxo": [
 ("The paramyxovirus fusion protein can only fuse membranes after:",["Proteolytic cleavage into F1 and F2 held by a disulfide bond","Binding sialic acid on the cell surface","Phosphorylation by the L protein of the nucleocapsid","Removal of the matrix protein layer"],0,"Availability of the activating protease therefore helps decide which tissues the virus can infect.",2),
 ("Which paramyxovirus attachment protein carries neuraminidase activity?",["HN of parainfluenza and mumps virus","H of measles virus","G of respiratory syncytial virus","F of all paramyxoviruses"],0,"HN binds sialic acid, so the virus must cleave sialic acid to avoid self-aggregation and to leave the cell; measles and respiratory syncytial virus bind protein receptors and need none.",2),
 ("The multinucleated giant cell formed in paramyxovirus infection is called a:",["Syncytium","Negri body","Koilocyte","Downey cell"],0,"Respiratory syncytial virus is named for exactly this effect."),
 ("Which protein of the paramyxovirus nucleocapsid is the RNA polymerase?",["L, the large protein","N, the nucleoprotein","P, the phosphoprotein","M, the matrix protein"],0,"P assists RNA synthesis and N maintains genome structure; the polymerase enters the cell as part of the nucleocapsid."),
 ("Paramyxovirus progeny leave the cell by:",["Budding from the plasma membrane without killing it","Lysing the cell they have infected","Exocytosis within Golgi-derived transport vesicles","Cell-to-cell bridges and nothing else"],0,"Much of the tissue damage therefore comes from the cell-mediated immune response rather than from the virus itself.",3)],
"measles": [
 ("Small grey lesions in the mouth before the maculopapular rash of measles are:",["Koplik spots","Aphthous ulcers","Forchheimer spots","Herpangina"],0,"They accompany high fever, cough, conjunctivitis, coryza and photophobia."),
 ("Measles virus spreads throughout the body as a viraemia in dendritic cells and lymphocytes because it binds:",["CD150, the signaling lymphocyte-activation molecule","Intercellular adhesion molecule-1 on lymphocytes","CD55, the decay accelerating factor","Sialic acid on surface glycoproteins"],0,"CD46 and nectin-4 give it access to epithelial and other cells; CD150 gives it the lymphoid route.",3),
 ("A neurological complication of measles appearing 5 to 7 years after the illness is:",["Subacute sclerosing panencephalitis","Postmeasles encephalitis in the acute phase","Guillain-Barré syndrome after the rash","Transverse myelitis during the fever"],0,"It is caused by a measles variant; postmeasles encephalitis follows the acute illness instead.",2),
 ("A child with a T-cell deficiency who catches measles is at particular risk of:",["Giant cell pneumonia","Fulminant hepatitis","Aplastic crisis","Myocarditis"],0,"Measles is also more severe where vitamin A is deficient.",3),
 ("Measles remains a major cause of death worldwide — about how many deaths in 2012?",["120,000","1,200","12,000","1.2 million"],0,"There were more than 10 million cases a year in unvaccinated populations; a live attenuated vaccine prevents it.")],
"mumps-rsv": [
 ("A barking, seal-like cough in a toddler suggests croup caused by:",["Parainfluenza virus","Respiratory syncytial virus","Mumps virus","Measles virus"],0,"Parainfluenza also causes common cold, bronchitis and pneumonia."),
 ("Parotitis with orchitis and aseptic meningitis in an unvaccinated adolescent points to:",["Mumps virus","Parainfluenza virus 4","Coxsackievirus B","Respiratory syncytial virus"],0,"A live attenuated vaccine prevents it, as it does measles.",2),
 ("Which virus is a life-threatening cause of bronchiolitis and pneumonia in premature infants, prevented by passive immunisation in high-risk babies?",["Respiratory syncytial virus","Parainfluenza virus type 1","Mumps virus in infancy","Rhinovirus in winter"],0,"Aerosol ribavirin is the antiviral option.",2)],
"flu-struct": [
 ("Influenza A and B differ from every other RNA virus of the respiratory tract in that they:",["Transcribe and replicate the genome in the nucleus","Have a plus-sense genome acting as messenger RNA","Lack a polymerase of their own","Assemble their virions in the Golgi"],0,"Assembly and budding still happen at the plasma membrane.",2),
 ("Amantadine is useless against influenza B because its target, the M2 ion channel:",["Is encoded only by influenza A","Is buried under hemagglutinin","Is non-functional in culture","Is also a neuraminidase"],0,"Zanamivir, oseltamivir and peramivir inhibit the neuraminidase of both A and B.",2),
 ("Baloxavir marboxil works by blocking the step in which influenza polymerase:",["Snatches caps from cellular messenger RNA to prime its own","Cleaves hemagglutinin into its active form","Exports the new nucleocapsids out of the nucleus","Adds a polyA tail to each transcript"],0,"The polymerase complex is PB1, PB2 and PA, bound with nucleoprotein to each negative-sense segment.",3),
 ("How many genome segments does influenza A carry?",["Eight","Seven","Three","One"],0,"Influenza C has seven; each segment is 890 to 2340 bases, and NS1 with NS2 and M1 with M2 share a segment each."),
 ("The extensive destruction of ciliated epithelium in influenza explains why patients:",["Develop secondary bacterial pneumonia","Become anosmic permanently","Develop bronchiectasis within days","Have a prolonged viraemia"],0,"The acute flu-like symptoms themselves come from massive cytokine release.",3)],
"flu-drift": [
 ("A new influenza pandemic strain arises when:",["Genome segments reassort between a human and an animal virus in a co-infected host","Point mutations accumulate in the hemagglutinin and neuraminidase genes","The virus integrates into the host chromosome","Neuraminidase is lost from the virion surface"],0,"Accumulated mutation — antigenic drift — gives the annual epidemics instead.",2),
 ("Antigenic drift is possible because the influenza polymerase:",["Has no proofreading","Copies DNA","Is shared with the host","Lacks a cap-snatching function"],0,"The segmented genome then adds reassortment on top of mutation."),
 ("Influenza A, unlike influenza B, is:",["A zoonosis infecting humans, other mammals and birds","Restricted to children under five years","Unable to cause pneumonia in healthy adults","Without any neuraminidase on its surface"],0,"Only influenza A therefore has an animal reservoir in which reassortment can generate pandemic strains.",2),
 ("The live attenuated influenza vaccine given by nasal spray is licensed for people aged:",["2 to 49 years","6 months and over","18 to 64 years","65 years and over"],0,"The inactivated vaccine contains hemagglutinin and neuraminidase of two influenza A strains and one or two influenza B strains.")],
}
